<script setup>
import {computed,reactive} from 'vue';import {Head,Link,router,usePage,useForm} from '@inertiajs/vue3';
const props=defineProps({canLogin:Boolean,canRegister:Boolean,databaseJobs:Object,categories:Array,locations:Array,topCompanies:Array,filters:Object,savedJobIds:Array});
const query=reactive({q:props.filters?.q||'',location:props.filters?.location||'',category:props.filters?.category||'',employment_type:[].concat(props.filters?.employment_type||[]).filter(Boolean),workplace_type:[].concat(props.filters?.workplace_type||[]).filter(Boolean),experience:props.filters?.experience||'',salary_min:Number(props.filters?.salary_min||0),posted:props.filters?.posted||'',sort:props.filters?.sort||'latest'});
const jobs=computed(()=>(props.databaseJobs?.data||[]).map((j,i)=>({id:j.id,slug:j.slug,age:j.published_at?new Date(j.published_at).toLocaleDateString():'Recently',logo:['🌈','●','◉','◒','◍','◌'][i%6],title:j.title||'Untitled role',company:j.company?.name||'Company',category:j.category?.name||'General',type:String(j.employment_type||'full_time').replaceAll('_',' '),salary:j.salary_visible&&j.salary_min?`$${Number(j.salary_min).toLocaleString()}–$${Number(j.salary_max||j.salary_min).toLocaleString()}`:'Salary undisclosed',place:[j.city,j.country].filter(Boolean).join(', ')||j.workplace_type||'Remote'})));
const page=usePage();const apply=()=>router.get(route('jobs.index'),query,{preserveState:true,replace:true});const clear=()=>router.get(route('jobs.index'));
const save=j=>{if(!page.props.auth.user)return router.visit(route('login'));if(page.props.auth.user.role==='candidate')router.post(route('jobs.save',j.id),{},{preserveScroll:true});};
const saved=id=>props.savedJobIds?.includes(id);const changeSort=e=>{query.sort=e.target.value;apply();};
const newsletter=useForm({email:''});const subscribe=()=>newsletter.post(route('newsletter.store'),{preserveScroll:true,onSuccess:()=>newsletter.reset()});
</script>
<template><Head title="Jobs"/><main><section class="hero"><div class="shade"/><header class="shell nav"><Link href="/" class="brand"><img src="/images/job-portal/brand-mark.svg">Job Portal</Link><nav><Link href="/">Home</Link><a class="active">Jobs</a><a>About Us</a><a>Contact Us</a></nav><div v-if="canLogin" class="auth"><Link v-if="$page.props.auth.user" :href="route('dashboard')">Dashboard</Link><template v-else><Link :href="route('login')">Login</Link><Link v-if="canRegister" class="btn" :href="route('register')">Register</Link></template></div></header><h1>Jobs</h1></section>
<section class="shell listings"><aside><form class="filters" @submit.prevent="apply"><h3>Search by Job Title</h3><label><img src="/images/job-portal/search.svg"><input v-model="query.q" placeholder="Job title or company"></label><h3>Location</h3><label><img src="/images/job-portal/location.svg"><select v-model="query.location"><option value="">Choose city</option><option v-for="city in locations" :value="city">{{city}}</option></select></label><div class="filter"><h3>Category</h3><label v-for="item in categories" :key="item.id"><span><input v-model="query.category" type="radio" name="category" :value="item.id"> {{item.name}}</span><small>{{item.jobs_count}}</small></label></div><div class="filter"><h3>Job Type</h3><label v-for="item in [['full_time','Full Time'],['part_time','Part Time'],['freelance','Freelance'],['contract','Contract']]" :key="item[0]"><span><input v-model="query.employment_type" type="checkbox" :value="item[0]"> {{item[1]}}</span></label></div><div class="filter"><h3>Workplace</h3><label v-for="item in ['onsite','remote','hybrid']" :key="item"><span><input v-model="query.workplace_type" type="checkbox" :value="item"> {{item}}</span></label></div><div class="filter"><h3>Experience Level</h3><select v-model="query.experience"><option value="">Any experience</option><option v-for="item in ['Entry level','Mid level','Senior','Lead']">{{item}}</option></select></div><div class="filter"><h3>Date Posted</h3><select v-model="query.posted"><option value="">Any time</option><option value="day">Last 24 hours</option><option value="week">Last 7 days</option><option value="month">Last 30 days</option></select></div><h3>Minimum Salary</h3><input v-model="query.salary_min" type="range" min="0" max="150000" step="5000"><div class="salary"><b>${{Number(query.salary_min).toLocaleString()}}+</b><button>Apply</button></div><button type="button" class="clear" @click="clear">Clear filters</button></form><div class="hiring"><img src="/images/job-portal/hiring.png"><div><h2>WE ARE HIRING</h2><p>Apply Today!</p></div></div></aside>
<div class="results"><div class="toolbar"><span>Showing {{jobs.length}} of {{databaseJobs?.total||jobs.length}} results</span><select :value="query.sort" @change="changeSort"><option value="latest">Sort by latest</option><option value="salary">Sort by salary</option></select></div><article v-for="j in jobs" :key="j.id" class="job"><small>{{j.age}}</small><button type="button" class="save" :class="{saved:saved(j.id)}" :aria-label="saved(j.id)?'Remove saved job':'Save job'" @click="save(j)">{{saved(j.id)?'♥':'♡'}}</button><div class="title"><b>{{j.logo}}</b><div><h2>{{j.title}}</h2><p>{{j.company}}</p></div></div><footer><div><span>▣ {{j.category}}</span><span>◷ {{j.type}}</span><span>▤ {{j.salary}}</span><span>⌖ {{j.place}}</span></div><Link class="details" :href="`/jobs/${j.slug}`">Job Details</Link></footer></article><div v-if="!jobs.length" class="empty">No jobs match your filters.</div><div class="pagination"><Link v-for="link in databaseJobs?.links||[]" :key="link.label" v-show="link.url" :href="link.url" class="outline" :class="{'details':link.active}" v-html="link.label"/></div></div></section>
<section class="top"><div class="shell"><header><h2>Top Company</h2><p>Discover verified employers actively hiring now.</p></header><div class="company-grid"><article v-for="(c,i) in topCompanies" :key="c.id"><b>{{['▣','◭','M','●'][i%4]}}</b><h3>{{c.name}}</h3><p>{{c.description||`${c.name} is looking for talented people to join the team.`}}</p><small>{{c.jobs_count}} open jobs</small></article></div></div></section>
<footer class="site-footer"><div class="shell foot"><div><b class="brand"><img src="/images/job-portal/brand-mark.svg">Job</b><p>Quis enim pellentesque viverra tellus eget malesuada facilisis. Congue nibh vivamus aliquet nunc mauris dui nullam et.</p></div><div><h3>Company</h3><a>About Us</a><a>Our Team</a><a>Partners</a><a>For Candidates</a><a>For Employers</a></div><div><h3>Job Categories</h3><a v-for="c in categories.slice(0,5)" :key="c.id">{{c.name}}</a></div><form @submit.prevent="subscribe"><h3>Newsletter</h3><p>Get new opportunities delivered to your inbox.</p><input v-model="newsletter.email" type="email" required placeholder="Email Address"><small v-if="newsletter.errors.email">{{newsletter.errors.email}}</small><button :disabled="newsletter.processing">Subscribe now</button></form></div><div class="shell copy"><span>© Copyright Job Portal 2024. Designed by Figma.guru</span><span>Privacy Policy　 Terms & Conditions</span></div></footer></main></template>
